--
-- TOC entry 404 (class 1255 OID 37976)
-- Name: create_tenant_schema(text, text[]); Type: FUNCTION; Schema: master_control; Owner: postgres
--

CREATE FUNCTION master_control.create_tenant_schema(p_schema_name text, p_biz_types text[] DEFAULT ARRAY['gas_station'::text]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
    v_sql TEXT;
BEGIN
    -- --------------------------------------------------------
    -- 1. Create the schema
    -- --------------------------------------------------------
    EXECUTE format('CREATE SCHEMA IF NOT EXISTS %I', p_schema_name);

    -- --------------------------------------------------------
    -- 2. CORE TABLES — present in every tenant schema
    -- --------------------------------------------------------

    -- 2a. tenant_businesses
    EXECUTE format($f$
        CREATE TABLE IF NOT EXISTS %I.tenant_businesses (
            biz_id       UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
            tenant_code  VARCHAR(50)  NOT NULL,
            biz_name     VARCHAR(200) NOT NULL,
            biz_type     VARCHAR(30)  NOT NULL
                             CHECK (biz_type IN ('gas_station','hotel','retail',
                                                  'restaurant','hr','pharmacy','salon')),
            gst_number   VARCHAR(20),
            pan_number   VARCHAR(10),
            address      TEXT,
            city         VARCHAR(100),
            state        VARCHAR(80),
            pincode      VARCHAR(10),
            phone        VARCHAR(15),
            email        VARCHAR(255),
            is_active    BOOLEAN      NOT NULL DEFAULT true,
            created_at   TIMESTAMPTZ  NOT NULL DEFAULT NOW()
        )
    $f$, p_schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_biz_tenant ON %I.tenant_businesses (tenant_code)',
                   replace(p_schema_name, '-', '_'), p_schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_biz_type   ON %I.tenant_businesses (biz_type)',
                   replace(p_schema_name, '-', '_'), p_schema_name);

    -- 2b. tenant_sub_users
    EXECUTE format($f$
        CREATE TABLE IF NOT EXISTS %I.tenant_sub_users (
            user_id         UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
            biz_id          UUID         NOT NULL REFERENCES %I.tenant_businesses(biz_id),
            l1_sub_user_id  UUID,
            full_name       VARCHAR(120) NOT NULL,
            email           VARCHAR(255) NOT NULL,
            password_hash   TEXT         NOT NULL,
            role            VARCHAR(30)  NOT NULL DEFAULT 'staff',
            department      VARCHAR(80),
            branch_code     VARCHAR(30),
            is_active       BOOLEAN      NOT NULL DEFAULT true,
            created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
            last_login      TIMESTAMPTZ
        )
    $f$, p_schema_name, p_schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_subuser_biz   ON %I.tenant_sub_users (biz_id)',
                   replace(p_schema_name, '-', '_'), p_schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_subuser_email ON %I.tenant_sub_users (email)',
                   replace(p_schema_name, '-', '_'), p_schema_name);

    -- 2c. user_module_access (RBAC per user per biz per module)
    EXECUTE format($f$
        CREATE TABLE IF NOT EXISTS %I.user_module_access (
            access_id   UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
            user_id     UUID        NOT NULL REFERENCES %I.tenant_sub_users(user_id),
            biz_id      UUID        NOT NULL REFERENCES %I.tenant_businesses(biz_id),
            module_code VARCHAR(50) NOT NULL,
            can_view    BOOLEAN     NOT NULL DEFAULT false,
            can_edit    BOOLEAN     NOT NULL DEFAULT false,
            can_delete  BOOLEAN     NOT NULL DEFAULT false,
            can_export  BOOLEAN     NOT NULL DEFAULT false,
            granted_by  UUID        REFERENCES %I.tenant_sub_users(user_id),
            granted_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            expires_at  TIMESTAMPTZ,
            CONSTRAINT uq_%s_user_biz_module UNIQUE (user_id, biz_id, module_code)
        )
    $f$, p_schema_name, p_schema_name, p_schema_name, p_schema_name,
         replace(p_schema_name, '-', '_'));

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_access_user_biz ON %I.user_module_access (user_id, biz_id)',
                   replace(p_schema_name, '-', '_'), p_schema_name);

    -- 2d. revenue_ledger
    EXECUTE format($f$
        CREATE TABLE IF NOT EXISTS %I.revenue_ledger (
            revenue_id      UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
            biz_id          UUID        NOT NULL REFERENCES %I.tenant_businesses(biz_id),
            txn_ref         VARCHAR(50) NOT NULL,
            source_stream   VARCHAR(100) NOT NULL,
            gross_amount    NUMERIC(14,2) NOT NULL,
            gst_amount      NUMERIC(12,2) NOT NULL DEFAULT 0,
            net_amount      NUMERIC(14,2) GENERATED ALWAYS AS (gross_amount - gst_amount) STORED,
            currency        CHAR(3)     NOT NULL DEFAULT 'INR',
            payment_method  VARCHAR(30)
                                CHECK (payment_method IN ('cash','card','upi','bank_transfer') OR payment_method IS NULL),
            recorded_by     UUID        REFERENCES %I.tenant_sub_users(user_id),
            txn_date        DATE        NOT NULL DEFAULT CURRENT_DATE,
            notes           TEXT,
            created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    $f$, p_schema_name, p_schema_name, p_schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_rev_biz_date ON %I.revenue_ledger (biz_id, txn_date DESC)',
                   replace(p_schema_name, '-', '_'), p_schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_rev_txn_ref  ON %I.revenue_ledger (txn_ref)',
                   replace(p_schema_name, '-', '_'), p_schema_name);

    -- 2e. expenses
    EXECUTE format($f$
        CREATE TABLE IF NOT EXISTS %I.expenses (
            expense_id    UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
            biz_id        UUID         NOT NULL REFERENCES %I.tenant_businesses(biz_id),
            category      VARCHAR(80)  NOT NULL,
            description   TEXT,
            net_amount    NUMERIC(14,2) NOT NULL,
            vendor_name   VARCHAR(150),
            vendor_gst    VARCHAR(20),
            expense_date  DATE         NOT NULL DEFAULT CURRENT_DATE,
            approved_by   UUID         REFERENCES %I.tenant_sub_users(user_id),
            status        VARCHAR(20)  NOT NULL DEFAULT 'pending'
                              CHECK (status IN ('pending','approved','rejected')),
            receipt_url   TEXT,
            created_at    TIMESTAMPTZ  NOT NULL DEFAULT NOW()
        )
    $f$, p_schema_name, p_schema_name, p_schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_exp_biz_date ON %I.expenses (biz_id, expense_date DESC)',
                   replace(p_schema_name, '-', '_'), p_schema_name);

    -- 2f. financial_releases
    EXECUTE format($f$
        CREATE TABLE IF NOT EXISTS %I.financial_releases (
            release_id      UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
            biz_id          UUID        NOT NULL REFERENCES %I.tenant_businesses(biz_id),
            release_type    VARCHAR(50) NOT NULL
                                CHECK (release_type IN ('salary_payout','vendor_payment','owner_draw')),
            total_released  NUMERIC(14,2) NOT NULL,
            release_status  VARCHAR(20) NOT NULL DEFAULT 'pending'
                                CHECK (release_status IN ('pending','processed','failed')),
            bank_ref        VARCHAR(100),
            released_by     UUID        REFERENCES %I.tenant_sub_users(user_id),
            release_date    DATE        NOT NULL DEFAULT CURRENT_DATE,
            notes           TEXT,
            created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    $f$, p_schema_name, p_schema_name, p_schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_releases_biz ON %I.financial_releases (biz_id, release_date DESC)',
                   replace(p_schema_name, '-', '_'), p_schema_name);

    -- --------------------------------------------------------
    -- 3. HR MODULE TABLES — created only when 'hr' is in p_biz_types
    -- --------------------------------------------------------
    IF 'hr' = ANY(p_biz_types) THEN

        -- 3a. hr_departments
        EXECUTE format($f$
            CREATE TABLE IF NOT EXISTS %I.hr_departments (
                dept_id      UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
                biz_id       UUID         NOT NULL REFERENCES %I.tenant_businesses(biz_id),
                dept_name    VARCHAR(100) NOT NULL,
                dept_code    VARCHAR(20),
                cost_centre  VARCHAR(50),
                head_emp_id  UUID,        -- FK added after hr_employees
                is_active    BOOLEAN      NOT NULL DEFAULT true,
                created_at   TIMESTAMPTZ  NOT NULL DEFAULT NOW()
            )
        $f$, p_schema_name, p_schema_name);

        EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_dept_biz ON %I.hr_departments (biz_id)',
                       replace(p_schema_name, '-', '_'), p_schema_name);

        -- 3b. hr_designations
        EXECUTE format($f$
            CREATE TABLE IF NOT EXISTS %I.hr_designations (
                designation_id UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
                biz_id         UUID         NOT NULL REFERENCES %I.tenant_businesses(biz_id),
                dept_id        UUID         REFERENCES %I.hr_departments(dept_id),
                title          VARCHAR(100) NOT NULL,
                grade          VARCHAR(20),
                level          INT,
                is_active      BOOLEAN      NOT NULL DEFAULT true
            )
        $f$, p_schema_name, p_schema_name, p_schema_name);

        -- 3c. hr_employees
        EXECUTE format($f$
            CREATE TABLE IF NOT EXISTS %I.hr_employees (
                emp_id            UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
                biz_id            UUID        NOT NULL REFERENCES %I.tenant_businesses(biz_id),
                emp_code          VARCHAR(20) NOT NULL,
                full_name         VARCHAR(120) NOT NULL,
                email             VARCHAR(255),
                phone             VARCHAR(15),
                alternate_phone   VARCHAR(15),
                date_of_birth     DATE,
                gender            VARCHAR(10),
                dept_id           UUID        REFERENCES %I.hr_departments(dept_id),
                designation_id    UUID        REFERENCES %I.hr_designations(designation_id),
                manager_emp_id    UUID        REFERENCES %I.hr_employees(emp_id),
                date_of_joining   DATE        NOT NULL,
                date_of_leaving   DATE,
                employment_type   VARCHAR(20) NOT NULL DEFAULT 'full_time'
                                      CHECK (employment_type IN ('full_time','part_time','contract','intern')),
                work_location     VARCHAR(100),
                status            VARCHAR(20) NOT NULL DEFAULT 'active'
                                      CHECK (status IN ('active','resigned','terminated','on_leave')),
                aadhar_no         VARCHAR(12),
                pan_no            VARCHAR(10),
                bank_account_no   VARCHAR(20),
                bank_ifsc         VARCHAR(11),
                bank_name         VARCHAR(100),
                profile_photo_url TEXT,
                created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                CONSTRAINT uq_%s_emp_code_biz UNIQUE (biz_id, emp_code)
            )
        $f$, p_schema_name, p_schema_name, p_schema_name, p_schema_name,
             p_schema_name, replace(p_schema_name, '-', '_'));

        EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_emp_biz    ON %I.hr_employees (biz_id)',
                       replace(p_schema_name, '-', '_'), p_schema_name);
        EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_emp_dept   ON %I.hr_employees (dept_id)',
                       replace(p_schema_name, '-', '_'), p_schema_name);
        EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_emp_status ON %I.hr_employees (biz_id, status)',
                       replace(p_schema_name, '-', '_'), p_schema_name);

        -- Add dept head FK now that hr_employees exists
        EXECUTE format($f$
            ALTER TABLE %I.hr_departments
                ADD CONSTRAINT fk_%s_dept_head
                FOREIGN KEY (head_emp_id) REFERENCES %I.hr_employees(emp_id)
        $f$, p_schema_name, replace(p_schema_name, '-', '_'), p_schema_name);

        -- 3d. hr_attendance
        EXECUTE format($f$
            CREATE TABLE IF NOT EXISTS %I.hr_attendance (
