--

CREATE FUNCTION master_control.fn_get_schema_for_tenant(p_tenant_code character varying) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_schema TEXT;
BEGIN
    SELECT schema_name INTO v_schema
    FROM master_control.master_tenant_registry
    WHERE tenant_code = p_tenant_code
      AND is_active = true;
    RETURN v_schema;
END;
$$;


