--
-- TOC entry 293 (class 1255 OID 39062)
-- Name: fn_get_tenant_by_email(character varying); Type: FUNCTION; Schema: master_control; Owner: postgres
--

CREATE FUNCTION master_control.fn_get_tenant_by_email(p_email character varying) RETURNS TABLE(tenant_code character varying, schema_name character varying, user_type character varying, is_active boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT r.tenant_code, reg.schema_name, r.user_type, r.is_active
    FROM master_control.sub_user_routing_index r
    JOIN master_control.master_tenant_registry reg USING (tenant_code)
    WHERE lower(r.email) = lower(p_email)
    LIMIT 1;
END;
$$;


