--
-- TOC entry 362 (class 1255 OID 39064)
-- Name: fn_provision_tenant(character varying, character varying, character varying, integer, text[]); Type: FUNCTION; Schema: master_control; Owner: postgres
--

CREATE FUNCTION master_control.fn_provision_tenant(p_owner_email character varying, p_company_name character varying, p_tenant_code character varying, p_plan_id integer, p_biz_types text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_owner_id  UUID;
    v_schema    TEXT;
BEGIN
    SELECT user_id INTO v_owner_id
    FROM master_control.master_users
    WHERE email = lower(p_owner_email);

    IF v_owner_id IS NULL THEN
        RAISE EXCEPTION 'Owner email % not found in master_users', p_owner_email;
    END IF;

    v_schema := 'tenant_' || lower(replace(p_tenant_code, '-', '_'));

    INSERT INTO master_control.master_tenant_registry
        (tenant_code, owner_user_id, plan_id, company_name, schema_name)
    VALUES
        (p_tenant_code, v_owner_id, p_plan_id, p_company_name, v_schema);

    PERFORM master_control.create_tenant_schema(v_schema, p_biz_types);

    RETURN 'Tenant ' || p_tenant_code || ' provisioned with schema ' || v_schema;
END;
$$;


